201	  /**
202	   * Get the size of an internal block at the given index of a block group.
203	   *
204	   * @param dataSize Size of the block group only counting data blocks
205	   * @param cellSize The size of a striping cell
206	   * @param numDataBlocks The number of data blocks
207	   * @param idxInBlockGroup The logical index in the striped block group
208	   * @return The size of the internal block at the specified index
209	   */
210	  public static long getInternalBlockLength(long dataSize,
211	      int cellSize, int numDataBlocks, int idxInBlockGroup) {
212	    Preconditions.checkArgument(dataSize >= 0);
213	    Preconditions.checkArgument(cellSize > 0);
214	    Preconditions.checkArgument(numDataBlocks > 0);
215	    Preconditions.checkArgument(idxInBlockGroup >= 0);
216	    // Size of each stripe (only counting data blocks)
217	    final int stripeSize = cellSize * numDataBlocks;
218	    // If block group ends at stripe boundary, each internal block has an equal
219	    // share of the group
220	    final int lastStripeDataLen = (int)(dataSize % stripeSize);
221	    if (lastStripeDataLen == 0) {
222	      return dataSize / numDataBlocks;
223	    }
224	
225	    final int numStripes = (int) ((dataSize - 1) / stripeSize + 1);
226	    return (numStripes - 1L)*cellSize
227	        + lastCellSize(lastStripeDataLen, cellSize,
228	        numDataBlocks, idxInBlockGroup);
229	  }
