231	  /**
232	   * Compute the safe length given the internal block lengths.
233	   *
234	   * @param ecPolicy The EC policy used for the block group
235	   * @param blockLens The lengths of internal blocks
236	   * @return The safe length
237	   */
238	  public static long getSafeLength(ErasureCodingPolicy ecPolicy,
239	      long[] blockLens) {
240	    final int cellSize = ecPolicy.getCellSize();
241	    final int dataBlkNum = ecPolicy.getNumDataUnits();
242	    Preconditions.checkArgument(blockLens.length >= dataBlkNum);
243	    final int stripeSize = dataBlkNum * cellSize;
244	    long[] cpy = Arrays.copyOf(blockLens, blockLens.length);
245	    Arrays.sort(cpy);
246	    // full stripe is a stripe has at least dataBlkNum full cells.
247	    // lastFullStripeIdx is the index of the last full stripe.
248	    int lastFullStripeIdx =
249	        (int) (cpy[cpy.length - dataBlkNum] / cellSize);
250	    return lastFullStripeIdx * (long) stripeSize; // return the safeLength
251	    // TODO: Include lastFullStripeIdx+1 stripe in safeLength, if there exists
252	    // such a stripe (and it must be partial).
253	  }
