255	  private static int lastCellSize(int size, int cellSize, int numDataBlocks,
256	      int i) {
257	    if (i < numDataBlocks) {
258	      // parity block size (i.e. i >= numDataBlocks) is the same as
259	      // the first data block size (i.e. i = 0).
260	      size -= i*cellSize;
261	      if (size < 0) {
262	        size = 0;
263	      }
264	    }
265	    return size > cellSize? cellSize: size;
266	  }
