269	   * Given a byte's offset in an internal block, calculate the offset in
270	   * the block group.
271	   */
272	  public static long offsetInBlkToOffsetInBG(int cellSize, int dataBlkNum,
273	      long offsetInBlk, int idxInBlockGroup) {
274	    int cellIdxInBlk = (int) (offsetInBlk / cellSize);
275	    return cellIdxInBlk * cellSize * dataBlkNum // n full stripes before offset
276	        + idxInBlockGroup * cellSize // m full cells before offset
277	        + offsetInBlk % cellSize; // partial cell
278	  }
