400	    protected void recover() throws IOException {
401	      checkLocations(locs.length);
402	
403	      Map<Long, BlockRecord> syncBlocks = new HashMap<>(locs.length);
404	      final int dataBlkNum = ecPolicy.getNumDataUnits();
405	      final int totalBlkNum = dataBlkNum + ecPolicy.getNumParityUnits();
406	      //check generation stamps
407	      for (int i = 0; i < locs.length; i++) {
408	        DatanodeID id = locs[i];
409	        try {
410	          DatanodeID bpReg = getDatanodeID(bpid);
411	          InterDatanodeProtocol proxyDN = bpReg.equals(id) ?
412	              datanode : DataNode.createInterDataNodeProtocolProxy(id, conf,
413	              dnConf.socketTimeout, dnConf.connectToDnViaHostname);
414	          ExtendedBlock internalBlk = new ExtendedBlock(block);
415	          final long blockId = block.getBlockId() + blockIndices[i];
416	          internalBlk.setBlockId(blockId);
417	          ReplicaRecoveryInfo info = callInitReplicaRecovery(proxyDN,
418	              new RecoveringBlock(internalBlk, null, recoveryId));
419	
420	          if (info != null &&
421	              info.getGenerationStamp() >= block.getGenerationStamp() &&
422	              info.getNumBytes() > 0) {
423	            final BlockRecord existing = syncBlocks.get(blockId);
424	            if (existing == null ||
425	                info.getNumBytes() > existing.rInfo.getNumBytes()) {
426	              // if we have >1 replicas for the same internal block, we
427	              // simply choose the one with larger length.
428	              // TODO: better usage of redundant replicas
429	              syncBlocks.put(blockId, new BlockRecord(id, proxyDN, info));
430	            }
431	          }
432	        } catch (RecoveryInProgressException ripE) {
433	          InterDatanodeProtocol.LOG.warn(
434	              "Recovery for replica " + block + " on data-node " + id
435	                  + " is already in progress. Recovery id = "
436	                  + rBlock.getNewGenerationStamp() + " is aborted.", ripE);
437	          return;
438	        } catch (IOException e) {
439	          InterDatanodeProtocol.LOG.warn("Failed to recover block (block="
440	              + block + ", datanode=" + id + ")", e);
441	        }
442	      }
443	      checkLocations(syncBlocks.size());
444	
445	      final long safeLength = getSafeLength(syncBlocks);
446	      if (LOG.isDebugEnabled()) {
447	        LOG.debug("Recovering block " + block
448	            + ", length=" + block.getNumBytes() + ", safeLength=" + safeLength
449	            + ", syncList=" + syncBlocks);
450	      }
451	
452	      // If some internal blocks reach the safe length, convert them to RUR
453	      List<BlockRecord> rurList = new ArrayList<>(locs.length);
454	      for (BlockRecord r : syncBlocks.values()) {
455	        int blockIndex = (int) (r.rInfo.getBlockId() & BLOCK_GROUP_INDEX_MASK);
456	        long newSize = getInternalBlockLength(safeLength, ecPolicy.getCellSize(),
457	            dataBlkNum, blockIndex);
458	        if (r.rInfo.getNumBytes() >= newSize) {
459	          rurList.add(r);
460	        }
461	      }
462	      assert rurList.size() >= dataBlkNum : "incorrect safe length";
463	
464	      // Recovery the striped block by truncating internal blocks to the safe
465	      // length. Abort if there is any failure in this step.
466	      truncatePartialBlock(rurList, safeLength);
467	
468	      // notify Namenode the new size and locations
469	      final DatanodeID[] newLocs = new DatanodeID[totalBlkNum];
470	      final String[] newStorages = new String[totalBlkNum];
471	      for (int i = 0; i < blockIndices.length; i++) {
472	        newLocs[blockIndices[i]] = DatanodeID.EMPTY_DATANODE_ID;
473	        newStorages[blockIndices[i]] = "";
474	      }
475	      for (BlockRecord r : rurList) {
476	        int index = (int) (r.rInfo.getBlockId() &
477	            HdfsServerConstants.BLOCK_GROUP_INDEX_MASK);
478	        newLocs[index] = r.id;
479	        newStorages[index] = r.storageID;
480	      }
481	      ExtendedBlock newBlock = new ExtendedBlock(bpid, block.getBlockId(),
482	          safeLength, recoveryId);
483	      DatanodeProtocolClientSideTranslatorPB nn = getActiveNamenodeForBP(bpid);
484	      nn.commitBlockSynchronization(block, newBlock.getGenerationStamp(),
485	          newBlock.getNumBytes(), true, false, newLocs, newStorages);
486	    }
