488	    private void truncatePartialBlock(List<BlockRecord> rurList,
489	        long safeLength) throws IOException {
490	      int cellSize = ecPolicy.getCellSize();
491	      int dataBlkNum = ecPolicy.getNumDataUnits();
492	      List<DatanodeID> failedList = new ArrayList<>();
493	      for (BlockRecord r : rurList) {
494	        int blockIndex = (int) (r.rInfo.getBlockId() & BLOCK_GROUP_INDEX_MASK);
495	        long newSize = getInternalBlockLength(safeLength, cellSize, dataBlkNum,
496	            blockIndex);
497	        try {
498	          r.updateReplicaUnderRecovery(bpid, recoveryId, r.rInfo.getBlockId(),
499	              newSize);
500	        } catch (IOException e) {
501	          InterDatanodeProtocol.LOG.warn("Failed to updateBlock (newblock="
502	              + ", datanode=" + r.id + ")", e);
503	          failedList.add(r.id);
504	        }
505	      }
506	
507	      // If any of the data-nodes failed, the recovery fails, because
508	      // we never know the actual state of the replica on failed data-nodes.
509	      // The recovery should be started over.
510	      if (!failedList.isEmpty()) {
511	        throw new IOException("Cannot recover " + block
512	            + ", the following datanodes failed: " + failedList);
513	      }
514	    }
