146	  private BlockLengths[] getBlockLengthsSuite() {
147	    final int groups = 4;
148	    final int minNumCell = 1;
149	    final int maxNumCell = stripesPerBlock;
150	    final int minNumDelta = -4;
151	    final int maxNumDelta = 2;
152	    BlockLengths[] suite = new BlockLengths[groups];
153	    Random random = ThreadLocalRandom.current();
154	    for (int i = 0; i < groups; i++) {
155	      int[] blockLengths = new int[dataBlocks + parityBlocks];
156	      for (int j = 0; j < blockLengths.length; j++) {
157	        // Choose a random number of cells for the block
158	        int numCell = random.nextInt(maxNumCell - minNumCell + 1) + minNumCell;
159	        // For data blocks, jitter the length a bit
160	        int numDelta = 0;
161	        if (i == groups - 1 && j < dataBlocks) {
162	          numDelta = random.nextInt(maxNumDelta - minNumDelta + 1) +
163	              minNumDelta;
164	        }
165	        blockLengths[j] = (cellSize * numCell) + (bytesPerChecksum * numDelta);
166	      }
167	      suite[i] = new BlockLengths(ecPolicy, blockLengths);
168	    }
169	    return suite;
