210	  /**
211	   * Write a file with blocks of different lengths.
212	   *
213	   * This method depends on completing before the DFS socket timeout.
214	   * Otherwise, the client will mark timed-out streamers as failed, and the
215	   * write will fail if there are too many failed streamers.
216	   *
217	   * @param blockLengths lengths of blocks to write
218	   * @throws Exception
219	   */
220	  private void writePartialBlocks(int[] blockLengths) throws Exception {
221	    final FSDataOutputStream out = dfs.create(p);
222	    final DFSStripedOutputStream stripedOut = (DFSStripedOutputStream) out
223	        .getWrappedStream();
224	    int[] posToKill = getPosToKill(blockLengths);
225	    int checkingPos = nextCheckingPos(posToKill, 0);
226	    Set<Integer> stoppedStreamerIndexes = new HashSet<>();
227	    try {
228	      for (int pos = 0; pos < testFileLength; pos++) {
229	        out.write(StripedFileTestUtil.getByte(pos));
230	        if (pos == checkingPos) {
231	          for (int index : getIndexToStop(posToKill, pos)) {
232	            out.flush();
233	            stripedOut.enqueueAllCurrentPackets();
234	            LOG.info("Stopping block stream idx {} at file offset {} block " +
235	                    "length {}", index, pos, blockLengths[index]);
236	            StripedDataStreamer s = stripedOut.getStripedDataStreamer(index);
237	            waitStreamerAllAcked(s);
238	            waitByteSent(s, blockLengths[index]);
239	            stopBlockStream(s);
240	            stoppedStreamerIndexes.add(index);
241	          }
242	          checkingPos = nextCheckingPos(posToKill, pos);
243	        }
244	      }
245	    } finally {
246	      // Flush everything
247	      out.flush();
248	      stripedOut.enqueueAllCurrentPackets();
249	      // Wait for streamers that weren't killed above to be written out
250	      for (int i=0; i< blockLengths.length; i++) {
251	        if (stoppedStreamerIndexes.contains(i)) {
252	          continue;
253	        }
254	        StripedDataStreamer s = stripedOut.getStripedDataStreamer(i);
255	        LOG.info("Waiting for block stream idx {} to reach length {}", i,
256	            blockLengths[i]);
257	        waitStreamerAllAcked(s);
258	      }
259	      DFSTestUtil.abortStream(stripedOut);
260	    }
261	  }
